class Checker:
    def countBits(self, n, result):
        if not isinstance(n, int):
            return False
        if n < 0 or n > 100000:
            return False
        if not isinstance(result, list):
            return False
        if len(result) != n + 1:
            return False
        for i, v in enumerate(result):
            if not isinstance(v, int):
                return False
            if v < 0:
                return False
            if v != i.bit_count():
                return False
        return True

